import { z } from 'zod';
import {
  GuidanceDirectoryPathSchema,
  GuidanceReferenceNameSchema,
} from './guidance-references';

const REPOSITORY_NAME =
  /^https:\/\/github\.com\/[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+\/?$/;
const GUIDANCE_BRANCH_NAME_LENGTH = 500;
export const GuidanceSourceSchema = z.discriminatedUnion('kind', [
  z
    .object({
      kind: z.literal('file'),
      path: GuidanceDirectoryPathSchema.refine(
        (value) =>
          value.startsWith('/') ||
          /^[a-z]:[\\/]/i.test(value) ||
          /^\\\\[^\\/]+[\\/][^\\/]+/.test(value),
        'File sources require an absolute path',
      ),
    })
    .strict(),
  z
    .object({
      kind: z.literal('github'),
      repository: z.string().regex(REPOSITORY_NAME),
      branch: z.string().trim().min(1).max(GUIDANCE_BRANCH_NAME_LENGTH),
      path: GuidanceReferenceNameSchema,
    })
    .strict(),
]);

export const GuidanceSyncStatusSchema = z
  .object({
    checkedAt: z.string().datetime(),
    syncedAt: z.string().datetime(),
    error: z.enum(['source_unavailable', 'document_invalid']).optional(),
  })
  .strict();

export const GuidanceOriginSchema = z
  .object({ source: GuidanceSourceSchema, revision: z.string().min(1) })
  .strict();

export type GuidanceSource = z.infer<typeof GuidanceSourceSchema>;
export type GuidanceSyncStatus = z.infer<typeof GuidanceSyncStatusSchema>;
const GUIDANCE_SOURCE_TITLE_LENGTH = 500;
export const GuidanceSourceCreateSchema = z
  .object({
    title: z.string().trim().min(1).max(GUIDANCE_SOURCE_TITLE_LENGTH),
    source: GuidanceSourceSchema,
    isEnabled: z.boolean().default(true),
  })
  .strict();

export interface GuidanceSourceContent {
  markdown: string;
  images?: { source: string; dataUrl: string }[];
  revision: string;
}

export const GUIDANCE_SOURCE_BYTES = 50 * 1024 * 1024;
